import { useCallback, useEffect, useMemo, useState } from "react";
import { Check, Download as DownloadIcon, ExternalLink, FileUp } from "lucide-react";
// @ts-ignore wailsjs bindings are generated by wails build
import {
  InstallFromArchive,
  InstallSource,
  ListSources,
  OpenSourcePage,
} from "../../wailsjs/go/controllers/Installer";
// @ts-ignore wailsjs bindings are generated by wails build
import {
  GetEnabledServices,
  SetServiceEnabled,
} from "../../wailsjs/go/controllers/Services";
// @ts-ignore wailsjs bindings are generated by wails build
import { EventsOn } from "../../wailsjs/runtime";
import { useDialogs } from "../components/dialogs/DialogProvider";
import { useT } from "../lib/i18n";

export type SourceRow = {
  id: string;
  version: string;
  kind: string;
  labelKey: string;
  installed: boolean;
  manual: boolean;
  pageURL?: string;
  service: boolean;
};

type InstallProgress = {
  id: string;
  version: string;
  phase: "download" | "extract" | "done" | "error";
  bytes: number;
  total: number;
  percent: number;
  speedBps: number;
};

const KIND_ORDER = ["web-server", "database", "cache", "mail", "runtime", "tool"];

export default function Downloads() {
  const t = useT();
  const dialogs = useDialogs();
  const [rows, setRows] = useState<SourceRow[]>([]);
  const [enabled, setEnabled] = useState<Record<string, boolean>>({});
  const [active, setActive] = useState<Record<string, InstallProgress>>({});

  const refresh = useCallback(() => {
    ListSources().then((list: SourceRow[]) => setRows(list ?? [])).catch(() => { /* pre-startup */ });
    GetEnabledServices().then((map: Record<string, boolean>) => setEnabled(map ?? {})).catch(() => { /* pre-startup */ });
  }, []);

  useEffect(() => {
    refresh();
    // @ts-ignore EventsOn returns a cancel function
    return EventsOn("install:progress", (p: InstallProgress) => {
      setActive((current) => ({ ...current, [p.id]: p }));
    });
  }, [refresh]);

  useEffect(() => {
    // @ts-ignore EventsOn returns a cancel function
    return EventsOn("install:done", (done: { id: string; version: string; ok?: boolean; error?: string }) => {
      setActive((current) => {
        const next = { ...current };
        delete next[done.id];
        return next;
      });
      refresh();
      if (!done.ok && done.error) {
        void dialogs.alert({
          title: t("downloads.failed", { id: done.id, version: done.version, reason: "" }).trim(),
          message: done.error,
        });
      }
    });
  }, [dialogs, refresh, t]);

  const grouped = useMemo(() => {
    const byKind = new Map<string, SourceRow[]>();
    for (const row of rows) {
      const bucket = byKind.get(row.kind) ?? [];
      bucket.push(row);
      byKind.set(row.kind, bucket);
    }
    return KIND_ORDER.filter((kind) => byKind.has(kind)).map((kind) => ({ kind, items: byKind.get(kind)! }));
  }, [rows]);

  return (
    <div className="space-y-4">
      <header>
        <h1 className="text-lg font-semibold text-white/95">{t("downloads.title")}</h1>
        <p className="text-xs text-white/50">{t("downloads.subtitle")}</p>
      </header>

      {grouped.map(({ kind, items }) => (
        <section key={kind} className="space-y-2">
          <h2 className="text-xs font-semibold uppercase tracking-wide text-white/40">
            {t(`downloads.kind.${kind}`)}
          </h2>
          <div className="grid grid-cols-1 gap-2 md:grid-cols-2">
            {items.map((row) => (
              <SourceCard
                key={row.id + row.version}
                row={row}
                progress={active[row.id]}
                dashboardVisible={enabled[row.id] === true}
                onToggleDashboard={async (visible) => {
                  await SetServiceEnabled(row.id, visible);
                  setEnabled((current) => ({ ...current, [row.id]: visible }));
                }}
              />
            ))}
          </div>
        </section>
      ))}
    </div>
  );
}

function SourceCard({
  row,
  progress,
  dashboardVisible,
  onToggleDashboard,
}: {
  row: SourceRow;
  progress?: InstallProgress;
  dashboardVisible: boolean;
  onToggleDashboard: (visible: boolean) => Promise<void>;
}) {
  const t = useT();
  const installing = progress !== undefined;
  const label = t(row.labelKey);

  return (
    <article className="glass flex flex-col gap-3 p-4">
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0">
          <h3 className="truncate text-sm font-semibold text-white/90">{label}</h3>
          <p className="text-[11px] text-white/40">{row.version}</p>
        </div>
        {row.installed && !installing && (
          <span className="flex items-center gap-1 rounded-full border border-emerald-400/30 bg-emerald-400/10 px-2 py-0.5 text-[10px] text-emerald-300">
            <Check className="h-3 w-3" /> {t("downloads.action.installed")}
          </span>
        )}
      </div>

      {installing && progress ? (
        <div>
          <div className="mb-1 flex justify-between text-[11px] text-white/60">
            <span>
              {progress.phase === "download" ? t("downloads.action.installing") : t("downloads.action.installing")}
              {" · "}
              {progress.phase}
            </span>
            <span>{progress.percent}%</span>
          </div>
          <div className="h-1.5 overflow-hidden rounded-full bg-white/10">
            <div
              className="h-full rounded-full bg-gradient-to-r from-accent to-accent2 transition-[width] duration-300"
              style={{ width: `${Math.min(100, Math.max(2, progress.percent))}%` }}
            />
          </div>
        </div>
      ) : row.manual && !row.installed ? (
        <div className="space-y-2">
          <p className="text-[11px] leading-relaxed text-white/50">{t("downloads.manualHint")}</p>
          <div className="flex gap-2">
            {row.pageURL && (
              <button
                type="button"
                onClick={() => void OpenSourcePage(row.id)}
                className="flex items-center gap-1.5 rounded-md bg-accent px-3 py-1.5 text-xs font-medium text-white hover:bg-accent/85"
              >
                <ExternalLink className="h-3 w-3" /> {t("downloads.action.openPage")}
              </button>
            )}
            <button
              type="button"
              onClick={() => void InstallFromArchive(row.id, row.version)}
              className="flex items-center gap-1.5 rounded-md border border-white/10 bg-white/5 px-3 py-1.5 text-xs text-white/80 hover:bg-white/10"
            >
              <FileUp className="h-3 w-3" /> {t("downloads.action.fromFile")}
            </button>
          </div>
        </div>
      ) : (
        <button
          type="button"
          disabled={row.installed}
          onClick={() => void InstallSource(row.id, row.version)}
          className="flex items-center justify-center gap-1.5 rounded-md bg-accent px-3 py-1.5 text-xs font-medium text-white hover:bg-accent/85 disabled:opacity-40"
        >
          <DownloadIcon className="h-3 w-3" />
          {row.installed ? t("downloads.action.installed") : t("downloads.action.install")}
        </button>
      )}

      {row.service && (
        <label className="flex cursor-pointer items-center gap-2 text-[11px] text-white/55">
          <input
            type="checkbox"
            checked={dashboardVisible}
            onChange={(event) => void onToggleDashboard(event.target.checked)}
            className="h-3.5 w-3.5 accent-[var(--c-accent)]"
          />
          {t("downloads.showOnDashboard")}
        </label>
      )}
    </article>
  );
}
